 // Comptes parents créés à la validation d'une pré-inscription ; mots de passe temporaires (jamais stockés en clair)
 const mdpTemp=()=>{const c='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';return Array.from(crypto.randomBytes(10),b=>c[b%c.length]).join('')};
 const texteId=(email,mdp,intro)=>`${intro}\n\nAdresse e-mail : ${email}\nMot de passe temporaire : ${mdp}\n${process.env.PUBLIC_URL?'Connexion : '+process.env.PUBLIC_URL+'\n':''}\nChangez ce mot de passe dès votre première connexion (menu « Mon profil »).`;
 async function creerCompteParent(p, eleveId, userId) {
  const email=p.parent_email.trim().toLowerCase();let u=await db.prepare('SELECT id,role,deleted_at FROM users WHERE lower(email)=?').get(email),mdp=null,cree=false;
  if(u&&u.role!=='parent')throw err(409,'Cette adresse e-mail appartient déjà à un compte qui n\'est pas un compte parent');
  if(u&&u.deleted_at)throw err(409,'Cette adresse e-mail correspond à un compte supprimé');
  if(!u){mdp=mdpTemp();const id=(await db.prepare('INSERT INTO users(email,password_hash,nom,role,mdp_temporaire) VALUES(?,?,?,?,1)').run(email,bcrypt.hashSync(mdp,10),p.parent_nom,'parent')).lastInsertRowid;u={id};cree=true;await audit(userId,'users',id,'create',null,{email,role:'parent',origine:'preinscription'})}
  if(eleveId)await db.prepare('INSERT OR IGNORE INTO parent_eleve VALUES(?,?)').run(u.id,eleveId);
  return{parentId:u.id,email,mdp,cree}}
 function infoCompte(c,p){if(c.cree)mail([c.parentId],'Votre compte - '+(db.ecoleNom||'École'),texteId(c.email,c.mdp,`Bonjour,\n\nLa pré-inscription de ${p.prenom} ${p.nom} a été validée. Votre compte parent est créé.`),'identifiants',c.parentId);
  return{cree:c.cree,email:c.email,mdp:c.mdp,email_envoye:c.cree&&mailer.actif()}}
 app.put('/api/preinscriptions/:id/statut',auth,roles('admin','comptable'),async (q, r) => {const d=parse(z.object({statut:z.enum(['validee','refusee'])}),q.body);const p=await db.prepare('SELECT * FROM preinscriptions WHERE id=?').get(q.params.id);if(!p)throw err(404,'Introuvable');if(p.statut!=='en_attente')throw err(409,'Déjà traitée');
  const c=await db.transaction(async () => {await db.prepare('UPDATE preinscriptions SET statut=? WHERE id=?').run(d.statut,p.id);let cp=null;
   if(d.statut==='validee'){const an=await annee();const eid=(await db.prepare('INSERT INTO eleves(nom,prenom,date_naissance,annee_entree,annee_scolaire) VALUES(?,?,?,?,?)').run(p.nom,p.prenom,p.date_naissance,an.slice(0,4),an)).lastInsertRowid;await db.prepare('UPDATE preinscriptions SET eleve_id=? WHERE id=?').run(eid,p.id);cp=await creerCompteParent(p,eid,q.user.id)}
   await audit(q.user.id,'preinscriptions',p.id,d.statut);return cp})();
  r.json({ok:true,compte:c?infoCompte(c,p):null})});
 app.post('/api/preinscriptions/:id/compte',auth,roles('admin','comptable'),async (q, r) => {const p=await db.prepare('SELECT * FROM preinscriptions WHERE id=?').get(q.params.id);if(!p)throw err(404,'Introuvable');if(p.statut!=='validee')throw err(409,"La pré-inscription n'est pas validée");
  const eid=p.eleve_id||((await db.prepare('SELECT id FROM eleves WHERE nom=? AND prenom=? AND date_naissance=? AND deleted_at IS NULL ORDER BY id DESC').get(p.nom,p.prenom,p.date_naissance))||{}).id;if(!eid)throw err(404,'Dossier élève introuvable pour cette pré-inscription');
  const c=await db.transaction(async () => {await db.prepare('UPDATE preinscriptions SET eleve_id=? WHERE id=?').run(eid,p.id);return await creerCompteParent(p,eid,q.user.id);})();r.json({ok:true,compte:infoCompte(c,p)})});
