 app.post('/api/tarifs/appliquer',auth,roles('admin','comptable'),async (q, r) => {const an=await annee();let n=0;await db.transaction(async () => {for(const t of await db.prepare('SELECT * FROM tarifs WHERE annee_scolaire=?').all(an))for(const e of await db.prepare('SELECT e.id FROM eleves e JOIN classes c ON c.id=e.classe_id WHERE e.deleted_at IS NULL AND c.niveau=?').all(t.niveau)){
   if(!(await db.prepare('SELECT 1 FROM frais WHERE eleve_id=? AND libelle=? AND annee_scolaire=?').get(e.id,t.libelle,an))){await db.prepare('INSERT INTO frais(eleve_id,libelle,montant_millimes,annee_scolaire) VALUES(?,?,?,?)').run(e.id,t.libelle,t.montant_millimes,an);n++}}await audit(q.user.id,'frais',null,'appliquer_tarifs',null,{n})})();r.json({frais_crees:n})});
 // Affectation automatique selon l'âge au 1er septembre (6 ans = 1re année … 11 ans = 6e année)
 const NIV=['1re année','2e année','3e année','4e année','5e année','6e année'];
 app.post('/api/eleves/:id/affecter-auto',auth,roles('admin','comptable'),async (q, r) => {const e=await db.prepare('SELECT * FROM eleves WHERE id=? AND deleted_at IS NULL').get(q.params.id);if(!e)throw err(404,'Introuvable');
  const an=await annee(),b=new Date(e.date_naissance+'T00:00:00');let age=+an.slice(0,4)-b.getFullYear();if(b.getMonth()>8||(b.getMonth()===8&&b.getDate()>1))age-=1;const niveau=NIV[age-6];
  if(!niveau)throw err(400,`Âge hors du cycle primaire (${age} ans au 1er septembre ; 6 à 11 ans attendus)`);
  const c=(await db.prepare('SELECT c.id,c.capacite,(SELECT COUNT(*) FROM eleves x WHERE x.classe_id=c.id AND x.deleted_at IS NULL) n FROM classes c WHERE c.niveau=? AND c.annee_scolaire=? AND c.deleted_at IS NULL ORDER BY n').all(niveau,an)).find(x=>x.n<x.capacite);
  if(!c)throw err(409,`Aucune classe de ${niveau} avec une place disponible pour ${an}`);await db.prepare('UPDATE eleves SET classe_id=? WHERE id=?').run(c.id,e.id);await audit(q.user.id,'eleves',e.id,'affectation_auto',{classe_id:e.classe_id},{classe_id:c.id});r.json({classe_id:c.id,niveau,age})});
